import {savedManagerDrivers,rememberManagerDriver} from './manager-drivers.js?v=0.15.3';
import {formatPhone,scheduledInstant} from './domain.js?v=0.15.3';
import {parsePairingCode,dispatchCall,sealDispatch} from './dispatch.js?v=0.15.3';
import {openTicketScanner} from './scanner-ui.js?v=0.15.3';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='delivery-manager-manager-v1';let config;try{config=JSON.parse(localStorage.getItem(key)||'null');}catch{}let draft,packet;try{draft=JSON.parse(localStorage.getItem('dm-manager-draft-'+config?.id)||'[]');packet=JSON.parse(localStorage.getItem('dm-manager-outbox-'+config?.id)||'null');}catch{draft=[];}let draftKind=localStorage.getItem('dm-manager-kind-'+config?.id)||'single';let error='',sending=false,statuses=[];let drivers=savedManagerDrivers(localStorage);if(config)config=drivers.find(c=>c.id===config.id)||config;
const persist=()=>{localStorage.setItem('dm-manager-kind-'+config.id,draftKind);localStorage.setItem('dm-manager-draft-'+config.id,JSON.stringify(draft));packet?localStorage.setItem('dm-manager-outbox-'+config.id,JSON.stringify(packet)):localStorage.removeItem('dm-manager-outbox-'+config.id);};
function render(){$('#manager').innerHTML=`<header class="manager-brand"><img src="icon.svg" alt=""><div><h1>Mike’s Dispatch</h1><p>Add orders. Send them to your driver.</p></div></header>${drivers.length?`<section class="card manager-driver-choice"><label for="dispatch-driver">Send orders to</label><select id="dispatch-driver" ${sending||draft.length||packet?'disabled':''}><option value="">Choose a saved driver</option>${drivers.map(c=>`<option value="${esc(c.id)}" ${c.id===config?.id?'selected':''}>${esc(c.driverName||'Driver')} · ${c.mode==='test'?'Test':'Live'}</option>`).join('')}</select><p class="muted">Pair each phone once. Choose the driver here at the start of a shift. Finish the current addition before switching.</p>${config?'<button id="rename-driver">Rename driver</button>':''}</section>`:''}${config?`<div class="${config.mode==='test'?'demo-banner':'hint'}"><strong>${config.mode==='test'?'TEST DISPATCH — fictional orders only':'LIVE DISPATCH — real driver records'}</strong></div><section class="card"><h2>Build an addition</h2><p>Every order sent together gets the same color on the driver’s phone. Order below is the requested stop order; due-soon scheduled orders can move first.</p>${draft.map((d,i)=>`<div class="manager-stop"><div><strong>${i+1}. ${esc(d.name||'Delivery')}</strong><p>${esc(d.address)}</p>${d.scheduledAt?'<span class="badge scheduled">Scheduled</span>':''}</div><div>${!packet?`<button data-edit="${i}">Edit</button><button data-up="${i}" ${i===0?'disabled':''}>↑</button><button data-down="${i}" ${i===draft.length-1?'disabled':''}>↓</button><button data-remove="${i}">Remove</button>`:''}</div></div>`).join('')}<div class="actions"><button id="add" class="primary" ${packet||draft.length>=12?'disabled':''}>+ Add order</button></div><label for="send-kind">Send these orders as</label><select id="send-kind" ${packet?'disabled':''}><option value="single">${draft.length>1?'Separate single deliveries':'Single delivery'}</option><option value="batch">One batch</option></select><p class="muted">One send = one addition. Orders arrive ready for delivery. The driver chooses when to start the run. Only additions are supported; contact the driver directly for corrections or cancellations.</p><button id="send" class="primary" ${sending||(!draft.length&&!packet)?'disabled':''}>${sending?'Sending…':packet?'Retry same addition':'Send addition to '+esc(config.driverName||'driver')}</button>${packet?'<p class="hint">A send is awaiting confirmation. Retry uses the same ID to prevent duplicates; editing is locked until it is resolved.</p>':''}</section><section class="card"><div class="row"><h2>Recent sends</h2><button id="refresh">Refresh status</button></div><p class="muted">Received means saved on the driver’s phone. Queued means awaiting collection; it expires after 24 hours.</p>${statuses.map(x=>`<p>${new Date(x.created_at).toLocaleString()} · <strong>${esc(x.status)}</strong></p>`).join('')||'<p>No sends checked yet.</p>'}</section><button id="unpair">Pair another driver</button><p class="muted">Order details are encrypted on this device before upload. The server deletes the encrypted copy after receipt or expiry. This phone keeps unsent drafts locally. Keep the pairing code private.</p>`:`<section class="card"><h2>Connect to a driver</h2><p>On the driver’s app, open Settings → Mike’s dispatch. Create a test or live pairing and paste its private code here.</p><form id="pair-form"><label for="driver-name">Driver name</label><input id="driver-name" maxlength="40" required placeholder="Tony or Charlotte"><label for="pair-code">Pairing code</label><textarea id="pair-code" required autocomplete="off" autocapitalize="off" spellcheck="false"></textarea><button class="primary">Connect manager</button></form></section>`}<p class="error" role="alert">${esc(error)}</p>`;
 bindDriverChoice();if(!config){$('#pair-form').onsubmit=async e=>{e.preventDefault();try{const c=parsePairingCode($('#pair-code').value.trim());await dispatchCall('status',{},c.token);config=rememberManagerDriver(localStorage,c,$('#driver-name').value);drivers=savedManagerDrivers(localStorage);draft=JSON.parse(localStorage.getItem('dm-manager-draft-'+c.id)||'[]');packet=JSON.parse(localStorage.getItem('dm-manager-outbox-'+c.id)||'null');draftKind=localStorage.getItem('dm-manager-kind-'+c.id)||'single';error='';render();}catch(e){error=e.message;render();}};return;}
 $('#send-kind').value=draftKind;$('#send-kind').onchange=()=>{draftKind=$('#send-kind').value;persist();};$('#add').onclick=()=>orderForm();$('#send').onclick=send;$('#refresh').onclick=refresh;$('#unpair').onclick=()=>{if(draft.length||packet)return fail('Finish or remove the current draft before changing pairing.');localStorage.removeItem(key);config=null;draft=[];packet=null;statuses=[];error='';render();};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>orderForm(Number(b.dataset.edit)));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{draft.splice(Number(b.dataset.remove),1);persist();render();});document.querySelectorAll('[data-up],[data-down]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.up??b.dataset.down),j=b.dataset.up!=null?i-1:i+1;[draft[i],draft[j]]=[draft[j],draft[i]];persist();render();});}
function fail(text){error=text;render();}
async function refresh(){const selected=config;try{const data=await dispatchCall('status',{},selected.token);if(config?.id!==selected.id)return;statuses=data.packets;error='';render();}catch(e){if(config?.id===selected.id)fail(e.message);}}
async function send(){if(sending)return;sending=true;const kind=$('#send-kind').value;render();try{if(!packet){packet=await sealDispatch(config,{version:1,mode:config.mode,kind,orders:draft});persist();}render();await dispatchCall('send',packet,config.token);packet=null;draft=[];draftKind='single';persist();error='';sending=false;await refresh();}catch(e){sending=false;fail(e.message);}}
function orderForm(index){if(packet)return;const d=draft[index]||{},scheduleDate=d.scheduledAt?new Date(d.scheduledAt):new Date(),savedTime=d.scheduledAt?String(scheduleDate.getHours()).padStart(2,'0')+':'+String(scheduleDate.getMinutes()).padStart(2,'0'):null,suggestedTime=String(Math.floor((Math.ceil((scheduleDate.getHours()*60+scheduleDate.getMinutes())/15)*15%1440)/60)).padStart(2,'0')+':'+String(Math.ceil(scheduleDate.getMinutes()/15)*15%60).padStart(2,'0'),times=Array.from({length:96},(_,i)=>String(Math.floor(i/4)).padStart(2,'0')+':'+String(i%4*15).padStart(2,'0')),modal=document.createElement('dialog');document.body.append(modal);modal.innerHTML=`<form><h2>${index==null?'Add order':'Edit order'}</h2><button id="manager-scan" type="button" class="primary">Scan ticket</button><p class="muted">Scanner setup uses the restaurant’s driver setup code once. Review the result before saving.</p><label>Customer name<input name="name" autocapitalize="words" value="${esc(d.name)}"></label><label>Customer phone<input name="phone" type="tel" inputmode="tel" value="${esc(d.phone)}"></label><label>Delivery address and unit<input name="address" required value="${esc(d.address)}" placeholder="Seattle street address and unit"></label><label>Ticket number<input name="ticket" inputmode="numeric" value="${esc(d.ticket)}"></label><label class="checkbox-label"><input id="manager-cold" name="cold" type="checkbox" ${d.hasColdItems?'checked':''}> Drinks or Ice Cream?</label><div id="manager-cold-details" ${d.hasColdItems?'':'hidden'}><label for="manager-cold-items">Which drinks and ice cream?</label><textarea id="manager-cold-items" name="coldItemDetails" maxlength="500" ${d.hasColdItems?'required':''} placeholder="For example: 2 Thai iced teas, 1 coconut ice cream">${esc(d.coldItemDetails)}</textarea><p class="muted">These items appear in the driver’s delivery confirmation.</p></div><label class="checkbox-label"><input id="manager-alcohol" name="alcohol" type="checkbox" ${d.hasAlcohol?'checked':''}> Alcohol?</label><div id="manager-alcohol-note" class="alcohol-reminder" ${d.hasAlcohol?'':'hidden'}>Bring an alcohol receipt for the customer to sign. The driver must check ID.</div><label class="checkbox-label"><input name="signature" type="checkbox" ${d.needsSignature?'checked':''}> Needs signature (tip / receipt)</label><label class="checkbox-label"><input id="manager-scheduled" name="isScheduled" type="checkbox" ${d.scheduledAt?'checked':''}> Scheduled Delivery?</label><div id="manager-schedule-fields" ${d.scheduledAt?'':'hidden'}><label for="manager-time">Requested delivery time</label><select id="manager-time" name="scheduledTime">${(savedTime&&!times.includes(savedTime)?[savedTime,...times]:times).map(value=>{const [h,m]=value.split(':').map(Number);return `<option value="${value}" ${value===(savedTime||suggestedTime)?'selected':''}>${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}</option>`;}).join('')}</select><p class="muted">${scheduleDate.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})} · 15-minute increments</p></div><label>Notes<textarea name="notes">${esc(d.notes)}</textarea></label><p class="error" role="alert"></p><div class="actions"><button id="cancel-order" type="button">Cancel</button><button class="primary">Save order</button></div></form>`;modal.showModal();const field=name=>modal.querySelector(`[name=${name}]`);modal.querySelector('#manager-cold').onchange=e=>{modal.querySelector('#manager-cold-details').hidden=!e.target.checked;field('coldItemDetails').required=e.target.checked;};modal.querySelector('#manager-alcohol').onchange=e=>{modal.querySelector('#manager-alcohol-note').hidden=!e.target.checked;};modal.querySelector('#manager-scheduled').onchange=e=>{modal.querySelector('#manager-schedule-fields').hidden=!e.target.checked;};field('phone').oninput=e=>{e.target.value=formatPhone(e.target.value);};const close=()=>{modal.close();modal.remove();};modal.querySelector('#cancel-order').onclick=close;modal.addEventListener('cancel',e=>{e.preventDefault();close();});modal.querySelector('#manager-scan').onclick=()=>openTicketScanner(result=>{for(const k of ['name','phone','address','ticket'])if(result.fields?.[k]||result[k])modal.querySelector(`[name=${k}]`).value=result.fields?.[k]||result[k];});modal.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),cold=!!f.get('cold');if(cold&&!f.get('coldItemDetails').trim()){modal.querySelector('.error').textContent='List the drinks or ice cream.';return;}const value={name:f.get('name').trim(),phone:formatPhone(f.get('phone').trim()),address:f.get('address').trim(),ticket:f.get('ticket').trim(),hasColdItems:cold,coldItemDetails:cold?f.get('coldItemDetails').trim():'',hasAlcohol:!!f.get('alcohol'),needsSignature:!!f.get('signature'),notes:f.get('notes').trim(),scheduledAt:f.get('isScheduled')?scheduledInstant(scheduleDate.toISOString(),f.get('scheduledTime')):null};if(index==null)draft.push(value);else draft[index]=value;persist();close();render();};}
render();

function bindDriverChoice(){const select=$('#dispatch-driver');if(select)select.onchange=()=>{if(sending||draft.length||packet){select.value=config?.id||'';return;}const chosen=drivers.find(c=>c.id===select.value);if(!chosen)return;config=chosen;localStorage.setItem(key,JSON.stringify(chosen));draft=JSON.parse(localStorage.getItem('dm-manager-draft-'+chosen.id)||'[]');packet=JSON.parse(localStorage.getItem('dm-manager-outbox-'+chosen.id)||'null');draftKind=localStorage.getItem('dm-manager-kind-'+chosen.id)||'single';statuses=[];error='';render();};if($('#rename-driver'))$('#rename-driver').onclick=()=>{const modal=document.createElement('dialog');modal.innerHTML=`<form><h2>Driver name</h2><label for="saved-driver-name">Name</label><input id="saved-driver-name" required maxlength="40" value="${esc(config.driverName||'')}"><div class="actions"><button type="button">Cancel</button><button class="primary">Save name</button></div></form>`;document.body.append(modal);modal.showModal();const close=()=>{modal.close();modal.remove();};modal.querySelector('[type=button]').onclick=close;modal.addEventListener('cancel',e=>{e.preventDefault();close();});modal.querySelector('form').onsubmit=e=>{e.preventDefault();config=rememberManagerDriver(localStorage,config,modal.querySelector('input').value);drivers=savedManagerDrivers(localStorage);close();render();};};}
